export const BATCH_YEARS = [2018, 2019, 2020, 2021, 2022];

export function getSummaryMetrics(batchYear = 'ALL') {
  const filtered = batchYear === 'ALL'
    ? PLACEMENT_STUDENTS
    : PLACEMENT_STUDENTS.filter(s => s.batchYear === Number(batchYear));

  const total = filtered.length;
  const onCampus = filtered.filter(s => s.status === 'On-Campus').length;
  const offCampusHS = filtered.filter(s => s.category.includes('Off-Campus') || s.category.includes('Higher Studies')).length;
  const notPlaced = filtered.filter(s => s.status === 'Not Placed').length;
  const placedTotal = onCampus + offCampusHS;
  const placementRate = total > 0 ? ((placedTotal / total) * 100).toFixed(1) : '0';

  let totalOffers = 0;
  let multiOfferStudents = 0;
  const companyCounts = {};

  filtered.forEach(s => {
    if (s.status === 'On-Campus') {
      totalOffers += s.offerCount;
      if (s.offerCount > 1) multiOfferStudents++;
      s.normalizedCompanies.forEach(c => {
        companyCounts[c] = (companyCounts[c] || 0) + 1;
      });
    }
  });

  const uniqueCompanies = Object.keys(companyCounts).length;
  const higherStudiesCount = filtered.filter(s => s.isHigherStudies).length;
  const startupCount = filtered.filter(s => s.isEntrepreneur).length;

  return {
    totalStudents: total,
    onCampusPlaced: onCampus,
    offCampusHigherStudies: offCampusHS,
    notPlaced,
    placedTotal,
    placementRate,
    totalOffers,
    multiOfferStudents,
    uniqueCompanies,
    higherStudiesCount,
    startupCount
  };
}

export function getYearOverYearTrends() {
  return BATCH_YEARS.map(year => {
    const yearStudents = PLACEMENT_STUDENTS.filter(s => s.batchYear === year);
    const total = yearStudents.length;
    const onCampus = yearStudents.filter(s => s.status === 'On-Campus').length;
    const offCampusHS = yearStudents.filter(s => s.category.includes('Off-Campus') || s.category.includes('Higher Studies')).length;
    const notPlaced = yearStudents.filter(s => s.status === 'Not Placed').length;
    const placed = onCampus + offCampusHS;
    const rate = total > 0 ? Number(((placed / total) * 100).toFixed(1)) : 0;
    const offers = yearStudents.reduce((acc, s) => acc + (s.status === 'On-Campus' ? s.offerCount : 0), 0);
    const multi = yearStudents.filter(s => s.status === 'On-Campus' && s.offerCount > 1).length;

    return {
      year: `${year}`,
      total,
      onCampus,
      offCampusHS,
      notPlaced,
      rate,
      offers,
      multi
    };
  });
}

export function getTopRecruiters(batchYear = 'ALL', limit = 12) {
  const filtered = batchYear === 'ALL'
    ? PLACEMENT_STUDENTS
    : PLACEMENT_STUDENTS.filter(s => s.batchYear === Number(batchYear));

  const counts = {};
  filtered.forEach(s => {
    if (s.status === 'On-Campus') {
      s.normalizedCompanies.forEach(c => {
        counts[c] = (counts[c] || 0) + 1;
      });
    }
  });

  return Object.entries(counts)
    .map(([company, count]) => ({ company, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

export function getOutcomeData(batchYear = 'ALL') {
  const m = getSummaryMetrics(batchYear);
  return [
    { name: 'On-Campus Placed', value: m.onCampusPlaced, color: '#2E4DE8' },
    { name: 'Higher Studies / Startups', value: m.offCampusHigherStudies, color: '#B8862A' },
    { name: 'Seeking Placement', value: m.notPlaced, color: '#B5432E' }
  ];
}

export function getMultiOfferData(batchYear = 'ALL') {
  const filtered = batchYear === 'ALL'
    ? PLACEMENT_STUDENTS
    : PLACEMENT_STUDENTS.filter(s => s.batchYear === Number(batchYear));

  const distribution = {
    '1 Offer': 0,
    '2 Offers': 0,
    '3 Offers': 0,
    '4+ Offers': 0
  };

  filtered.forEach(s => {
    if (s.status === 'On-Campus') {
      if (s.offerCount === 1) distribution['1 Offer']++;
      else if (s.offerCount === 2) distribution['2 Offers']++;
      else if (s.offerCount === 3) distribution['3 Offers']++;
      else if (s.offerCount >= 4) distribution['4+ Offers']++;
    }
  });

  return Object.entries(distribution).map(([category, count]) => ({ category, count }));
}

