export function getAlumniByCompany(companyName) {
  const target = companyName.toLowerCase();
  return PLACEMENT_STUDENTS.filter(s => {
    if (s.status !== 'On-Campus') return false;
    return s.normalizedCompanies.some(c => c.toLowerCase().includes(target)) ||
           s.details.toLowerCase().includes(target);
  });
}

